39	// mustJSON 把报告或记录序列化为 JSON 快照：序列化在取值当时展开全部指针，
40	// 之后即使报告与存储共享内存，快照里保存的仍是取值当时的原值。
41	func mustJSON(t *testing.T, v any) string {
42		t.Helper()
43		raw, err := json.Marshal(v)
44		if err != nil {
45			t.Fatalf("marshal: %v", err)
46		}
