68		// 快照里仍是原值，能识别出任何方向的串改。
69		firstSnapshot := mustJSON(t, first)
70		storedSnapshot := mustJSON(t, mustGetHandover(t, f, h.ID))
71		forge := time.Date(2031, 5, 6, 7, 8, 9, 0, time.UTC)
72	
73		// 班次摘要与班次上携带的结束时记录。
74		second.Shift.Owner = "篡改负责人"
75		*second.Shift.ClosedAt = forge
