597	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
598	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
599	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
600	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
601	// 最后一项成功接收使整份交接首次全部明确接收时，完成时间记为本次成功处理时间；
602	// 若记录里存在补齐前误写（或零值）的旧完成时间，一并以本次时间覆盖。本次处理失败、
603	// 退回或仍有未接收项时不写完成时间，交接不能提前完成。
604	// 只有本地数据保存成功才算处理完成：输入合法、该项允许处理、实际进入保存阶段后
605	// 写盘失败时，内存变更随快照一并回滚，返回原保存错误与零值交接结果（编号、岗位、
606	// 两班编号为空，发起时间为零值，完成时间为空，清单没有事项），不把本次尝试形成的
607	// 处理状态、操作人、处理时间或交接完成时间当作处理结果，也不返回失败前的整份交接；
608	// 最后一项的保存失败同样不能通过返回结果宣称整份交接完成。
609	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
610		handoverID = clean(handoverID)
611		itemID = clean(itemID)
612		operator = clean(operator)
613		reason = clean(reason)
614		trackingNote = clean(trackingNote)
615		nextFollowOwner = clean(nextFollowOwner)
616	
617		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
618			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
619		}
620		if err := requireNonEmpty("操作人", operator); err != nil {
621			return Handover{}, err
622		}
623	
624		var result Handover
625		err := svc.store.mutate(func(d *Data) error {
626			h, _ := findHandover(d, handoverID)
627			if h == nil {
628				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
629			}
630			e, _ := findEntry(h, itemID)
631			if e == nil {
632				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
633			}
634			if e.Status.Received() {
635				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
636					ErrHandoverState, e.ItemID, e.Status.Label())
637			}
638			if e.Status == EntryReturned {
639				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
640				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
641				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
642				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
643					ErrHandoverState, e.ItemID, h.ID)
644			}
645			switch action {
646			case ActionReturn:
647				if err := requireNonEmpty("退回原因", reason); err != nil {
648					return err
649				}
650			case ActionTrack:
651				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
652					return err
653				}
654				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
655					return err
656				}
657			}
658	
659			now := svc.now()
660			switch action {
661			case ActionConfirm:
662				e.Status = EntryConfirmed
663			case ActionTrack:
664				e.Status = EntryTracking
665				e.TrackingNote = trackingNote
666				e.FollowOwner = nextFollowOwner
667			case ActionReturn:
668				e.Status = EntryReturned
669				e.Rounds = append(e.Rounds, ReturnRound{
670					Seq:            len(e.Rounds) + 1,
671					ReturnedAt:     now,
672					ReturnOperator: operator,
673					Reason:         reason,
674				})
675			}
676			e.Operator = operator
677			e.ProcessedAt = &now
678	
679			if action != ActionReturn {
680				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
681				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
682					it.CurrentShiftID = h.ToShiftID
683					if !contains(it.ShiftIDs, h.ToShiftID) {
684						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
685					}
686					detail := receivedDetailText(h, action, e.Status.Label(), trackingNote, nextFollowOwner)
687					if action == ActionTrack {
688						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
689						it.FollowOwner = nextFollowOwner
690					}
691					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
692				}
693			}
694	
695			if h.Completed() {
696				// 完成时间记录这份交接真正接收齐全部事项的时刻：以最后一次成功
697				// 接收（确认或继续跟踪）的处理时间为准。旧数据可能在清单仍有结果
698				// 缺失、无法识别、待处理或退回项时就误写过完成时间（或只留下零值）：
699				// 接班人逐项补齐、整份交接首次全部明确接收时，用本次成功处理时间
700				// 覆盖那个旧时间，不能沿用补齐前的时刻；旧时间缺失（nil）时同样在
701				// 本次补上。未全部接收（如本次退回、仍有异常结果项）时不写入，
702				// 交接保持未完成。正常流程与空清单在首次全部接收时写入，之后已接收
703				// 项无法再处理，完成时间不会被改写。
704				h.CompletedAt = &now
705			}
706			// 返回独立副本：调用方保留的处理结果（含逐项处理时间、退回/补充记录
707			// 与完成时间）不与系统保存的交接共享内存。
708			result = cloneHandover(*h)
709			return nil
710		})
711		if err != nil {
712			// 业务拒绝或保存失败都不返回任何交接结果：保存失败时内存已随快照
713			// 回滚，不能把本次尝试形成但尚未保存的处理状态、操作人、处理时间
714			// 或交接完成时间当作处理结果交给调用方。
715			return Handover{}, err
716		}
717		return result, nil
718	}
719	
720	// validProcessedAt 报告处理时间是否真实记录：nil 或零值
721	// （0001-01-01T00:00:00Z）都视为未记录，不推测补齐。
722	func validProcessedAt(t *time.Time) bool { return t != nil && !t.IsZero() }
723	
724	func contains(xs []string, x string) bool {
725		for _, v := range xs {
726			if v == x {
727				return true
728			}
729		}
730		return false
731	}
732	
733	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
734	// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
735	// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
736	// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
737	// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
738	// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
739	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
740		handoverID = clean(handoverID)
741		itemID = clean(itemID)
742		operator = clean(operator)
743		supplement = clean(supplement)
744		if err := requireNonEmpty("操作人", operator); err != nil {
745			return Handover{}, err
746		}
747		if err := requireNonEmpty("补充说明", supplement); err != nil {
748			return Handover{}, err
749		}
750	
751		var result Handover
752		err := svc.store.mutate(func(d *Data) error {
753			h, _ := findHandover(d, handoverID)
754			if h == nil {
755				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
756			}
757			e, _ := findEntry(h, itemID)
758			if e == nil {
759				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
760			}
761			if e.Status != EntryReturned {
762				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
763					ErrHandoverState, e.ItemID, e.Status.Label())
764			}
765			if len(e.Rounds) == 0 {
766				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
767			}
768			round := &e.Rounds[len(e.Rounds)-1]
769			if round.ResubmittedAt != nil {
770				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
771			}
772			now := svc.now()
773			round.Supplement = supplement
774			round.SupplementOperator = operator
775			round.SupplementAt = &now
776			round.ResubmittedAt = &now
777			// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
778			// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
779			e.Status = EntryPending
780			e.Operator = ""
781			e.ProcessedAt = nil
782			// 返回独立副本：调用方保留的重新提交结果不与系统保存的交接共享内存。
783			result = cloneHandover(*h)
784			return nil
785		})
786		return result, err
787	}
