     "content":"退回缺时间","severity":"normal","follow_owner":"李四",
     "created_at":"2026-10-02T09:20:00+08:00",
     "events":[{"at":"2026-10-02T09:20:00+08:00","kind":"created","detail":"事项建立"}]},
