	text2 := FormatItemJourney(j2)
	if !strings.Contains(text2, "当前结果：继续跟踪（已接收）；处理人=未记录；处理时间=未记录") {
		t.Fatalf("零值时间的跟踪结果应显示未记录：\n%s", text2)
